136	function unitsOf(state: GameState, uid: string, specialUids: readonly string[]): string[] {
137	  const card = cardOfUid(state, uid);
138	  if (card === undefined) return ["Colorless"]; // unresolved uid — the conservative unit
139	  const program = programFor(card.id)?.energy;
140	  // Basic energy → its type; an unauthored special energy → Colorless.
