51	/** Every uid held anywhere on `seat`'s side, sorted — cards only ever MOVE
52	    between zones, so this multiset is invariant across a play. */
53	function seatUids(state: GameState, seat: Seat): string[] {
54	  const side = state.players[seat];
55	  const inPlay = [side.active, ...side.bench].flatMap((p) =>
56	    p === null ? [] : [...p.stack, ...p.energy, ...p.tools],
57	  );
58	  return [...side.deck, ...side.hand, ...side.discard, ...side.prizes, ...inPlay].sort();
59	}
