66	    discard — no uid leaves the game, so the state stays legal-shaped. */
67	function handOnly(state: GameState, seat: Seat, keep: string[]): GameState {
68	  const side = state.players[seat];
69	  const rest = side.hand.filter((u) => !keep.includes(u));
70	  return {
71	    ...state,
72	    players: {
73	      ...state.players,
74	      [seat]: { ...side, hand: keep, discard: [...side.discard, ...rest] },
75	    },
