89	  });
90	  if (spot === "active") {
91	    if (side.active === null) throw new Error(`${seat} has no Active`);
92	    return {
93	      ...state,
94	      players: { ...state.players, [seat]: { ...side, deck, active: put(side.active) } },
95	    };
96	  }
97	  if (side.bench[spot] === undefined) throw new Error(`${seat} has no benched Pokémon at ${spot}`);
