    const band = handUid(state, "p1", "sv01-197");
    expectErr(
      state,
      {
        type: "attachTool",
        seat: "p1",
        uid: band,
        target: null as unknown as { spot: "active" },
      },
      "BAD_TARGET",
    );
    expectErr(
      state,
      {
        type: "attachTool",
        seat: "p1",
        uid: band,
        target: { spot: "bench", index: "0" as unknown as number },
      },
