    );
    expectErr(
      state,
      { type: "attachTool", seat: "p1", uid: band, target: { spot: "bench", index: 4 } },
      "BAD_BENCH_INDEX",
    );
    // And a Tool routed through playTrainer is redirected, not played.
    expectErr(state, { type: "playTrainer", seat: "p1", uid: band }, "TRAINER_TYPE_UNSUPPORTED");
  });
